custom_fields.sky:
[[[
  const w = states['weather.dwelldeck_slot_295'];
  const sun = states['sun.sun'];
  const pv = states['sensor.dwelldeck_slot_286'];
  const condRaw = (w?.state || 'unknown').toLowerCase();
  const cond = condRaw.replaceAll('_', ' ');
  const temp = w?.attributes?.temperature;
  const hum = w?.attributes?.humidity;
  const wind = w?.attributes?.wind_speed;
  const windUnit = w?.attributes?.wind_speed_unit || 'km/h';
  const elev = Number(sun?.attributes?.elevation ?? -10);
  const az = Number(sun?.attributes?.azimuth ?? (sun?.state === 'above_horizon' ? 180 : 270));
  const pvW = pv && !['unknown','unavailable'].includes(pv.state) ? Math.round(Number(pv.state)) : null;
  const storm = ['lightning','lightning-rainy'].includes(condRaw);
  const rainy = ['rainy','pouring','lightning-rainy','hail','snowy-rainy'].includes(condRaw) || cond.includes('rain');
  const cloudy = storm || rainy || ['cloudy','partlycloudy','fog','windy','windy-variant','exceptional'].includes(condRaw);
  const night = sun?.state !== 'above_horizon';
  const nowMs = Date.now();
  const rise = sun?.attributes?.next_rising ? Date.parse(sun.attributes.next_rising) : NaN;
  const set = sun?.attributes?.next_setting ? Date.parse(sun.attributes.next_setting) : NaN;
  // HA's next_rising and next_setting are always future events.
  // During daytime, next_rising is tomorrow, so estimate today's rise from it.
  const todayRise = Number.isFinite(rise) ? rise - 86400000 : NaN;
  const progressTime = (!night && Number.isFinite(todayRise) && Number.isFinite(set) && set > todayRise)
    ? (nowMs - todayRise) / (set - todayRise) : NaN;
  const p = Math.max(0, Math.min(1, Number.isFinite(progressTime) ? progressTime : (az - 90) / 180));
  const fmtTime = ms => Number.isFinite(ms) ? new Date(ms).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '—';
  const sunriseDisplay = night ? rise : todayRise;
  const sunsetDisplay = set;
  const sunriseText = fmtTime(sunriseDisplay);
  const sunsetText = fmtTime(sunsetDisplay);
  // Approximate synodic lunar age; not a moon-position ephemeris.
  const lunarAge = (((nowMs - Date.UTC(2000,0,6,18,14)) / 86400000) % 29.530588853 + 29.530588853) % 29.530588853;
  const lunarFraction = lunarAge / 29.530588853;
  const moonPhase = lunarFraction < .035 || lunarFraction >= .965 ? 'New moon' : lunarFraction < .215 ? 'Waxing crescent' : lunarFraction < .285 ? 'First quarter' : lunarFraction < .465 ? 'Waxing gibbous' : lunarFraction < .535 ? 'Full moon' : lunarFraction < .715 ? 'Waning gibbous' : lunarFraction < .785 ? 'Last quarter' : 'Waning crescent';
  const illum = Math.round((1 - Math.cos(2 * Math.PI * lunarFraction)) * 50);
  const shadowX = Math.round(24 * Math.abs(Math.cos(2*Math.PI*lunarFraction)));
  const waxing = lunarFraction < .5;
  const sx = 18 + p * 264;
  const sy = 330 - (4 * p * (1 - p)) * 130;
  const skyTop = night ? '#07131f' : rainy ? '#5c6f82' : cloudy ? '#6d89a6' : (elev < 8 ? '#ff9a66' : '#49a8ff');
  const skyBottom = night ? '#101c2b' : rainy ? '#1f3146' : cloudy ? '#274764' : (elev < 8 ? '#5c4d80' : '#a6dbff');
  const horizon = night ? '#0a1623' : rainy ? '#173042' : '#214764';
  const arcColor = night ? 'rgba(151,177,203,.45)' : 'rgba(237,245,255,.45)';
  const sunColor = elev < 8 ? '#ffc078' : '#ffe18f';
  const stars = night ? `
    <g opacity="0.9">
      <circle cx="30" cy="70" r="1.5" fill="#ffffff" />
      <circle cx="72" cy="120" r="1.2" fill="#ffffff" />
      <circle cx="130" cy="88" r="1.4" fill="#ffffff" />
      <circle cx="234" cy="135" r="1.3" fill="#ffffff" />
      <circle cx="272" cy="60" r="1.5" fill="#ffffff" />
    </g>` : '';
  const sunOrMoon = night
    ? `<g transform="translate(244,92)">
         <circle cx="0" cy="0" r="16" fill="#dbe9ff" />
         <path d="${waxing ? 'M0,-16 A16,16 0 0 0 0,16' : 'M0,-16 A16,16 0 0 1 0,16'} A${Math.max(1,shadowX)},16 0 0 ${waxing ? 1 : 0} 0,-16 Z" fill="${skyTop}" />
       </g>`
    : `<g transform="translate(${sx-13},${sy-13})"><circle cx="13" cy="13" r="13" fill="${sunColor}" /><circle cx="13" cy="13" r="20" fill="none" stroke="${sunColor}" stroke-opacity="0.28" stroke-width="7"
/></g>`;
  const clouds = cloudy ? `
    <g class="drifting-clouds" opacity="0.96">
      <ellipse cx="86" cy="160" rx="26" ry="13" fill="#edf5ff" fill-opacity="0.95" />
      <ellipse cx="108" cy="155" rx="22" ry="14" fill="#edf5ff" fill-opacity="0.95" />
      <ellipse cx="128" cy="163" rx="28" ry="12" fill="#edf5ff" fill-opacity="0.92" />
      <rect x="74" y="164" width="72" height="15" rx="8" fill="#edf5ff" fill-opacity="0.93" />
    </g>` : '';
  const lightning = storm ? `
    <g class="thunder-flash">
      <path d="M173 164 L160 207 L173 207 L162 248 L194 200 L181 200 L194 164 Z" fill="#fff6c8" stroke="#ffffff" stroke-width="1.2" />
    </g>` : '';
  const rain = rainy ? `
    <g>
      <line class="rain" x1="82" y1="185" x2="76" y2="222" style="animation-delay:0s" />
      <line class="rain" x1="97" y1="190" x2="91" y2="229" style="animation-delay:.18s" />
      <line class="rain" x1="112" y1="188" x2="106" y2="229" style="animation-delay:.32s" />
      <line class="rain" x1="127" y1="189" x2="121" y2="230" style="animation-delay:.12s" />
      <line class="rain" x1="140" y1="190" x2="134" y2="226" style="animation-delay:.28s" />
      <line class="rain" x1="155" y1="185" x2="149" y2="223" style="animation-delay:.42s" />
    </g>` : '';
  const title = `${temp !== undefined ? Math.round(temp) + '°' : '—'} · ${cond.charAt(0).toUpperCase() + cond.slice(1)}`;
  const sub = `${hum != null ? 'Humidity ' + hum + '%' : 'Humidity —'} · ${wind != null ? 'Wind ' + wind + ' ' + windUnit : 'Wind —'}${pvW !== null ? ' · Solar ' + pvW + ' W' : ''}`;
  const sunText = night ? `${moonPhase} · ${illum}% illuminated` : `Sun ${elev.toFixed(1)}° above horizon`;
  return `
    <div style="position:relative;width:100%;height:100%;overflow:hidden;border-radius:16px;">
      <style>
        .villa-sky .rain { stroke:#a9dcff; stroke-width:2.2; stroke-linecap:round; opacity:.95; animation: rainFall 1.1s linear infinite; }
        @keyframes rainFall { 0% { transform: translateY(-6px); opacity: 0; } 20% { opacity: .95; } 100% { transform: translateY(17px); opacity: 0; } }
        .villa-sky .glow { animation: pulseGlow 4s ease-in-out infinite; transform-origin: center; }
        .villa-sky .drifting-clouds { animation: cloudsDrift 18s ease-in-out infinite alternate; }
        @keyframes cloudsDrift { from { transform: translateX(-24px); } to { transform: translateX(65px); } }
        .villa-sky .thunder-flash { opacity:0; animation: villaFlash 8s ease-in-out infinite; }
        @keyframes villaFlash { 0%,63%,67%,72%,100% { opacity:0; } 64%,66%,70% { opacity:1; } }
        @media (prefers-reduced-motion: reduce) { .villa-sky .rain, .villa-sky .glow, .villa-sky .drifting-clouds, .villa-sky .thunder-flash {animation:none !important;} }
        @keyframes pulseGlow { 0%,100% { opacity:.22; } 50% { opacity:.42; } }
      </style>
      <svg class="villa-sky" viewBox="0 0 300 420" width="100%" height="100%" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="skyGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="${skyTop}" />
            <stop offset="100%" stop-color="${skyBottom}" />
          </linearGradient>
        </defs>
        <rect x="0" y="0" width="300" height="420" rx="16" fill="url(#skyGrad)" />
        ${stars}
        <path d="M18 330 Q150 70 282 330" fill="none" stroke="${arcColor}" stroke-width="2.3" stroke-dasharray="4 4" />
        <circle cx="18" cy="330" r="2.8" fill="#ffd16b" fill-opacity="0.85" />
        <circle cx="282" cy="330" r="2.8" fill="#ffd16b" fill-opacity="0.85" />
        <line x1="0" y1="330" x2="300" y2="330" stroke="rgba(237,245,255,.18)" stroke-width="1" />
        <rect x="0" y="330" width="300" height="90" fill="${horizon}" fill-opacity="0.88" />
        ${night ? '' : `<circle class="glow" cx="${sx}" cy="${sy}" r="26" fill="${sunColor}" fill-opacity="0.18" />`}
        ${sunOrMoon}
        ${clouds}
        ${lightning}
        ${rain}
      </svg>
      <div style="position:absolute;left:10px;top:10px;right:10px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px;background:rgba(5,15,29,.83);border:1px solid rgba(255,255,255,.25);border-radius:12px;padding:12px;box-shadow:0 5px 18px rgba(0,0,0,.28);">
        <div>
          <div style="font-size:20px;font-weight:800;color:#ffffff;line-height:1.2;text-shadow:0 2px 3px rgba(0,0,0,.8);">${title}</div>
          <div style="font-size:14px;font-weight:700;color:#ffffff;margin-top:7px;line-height:1.5;text-shadow:0 1px 3px #000;">${sub}</div>
        </div>
        <div style="text-align:right;">
          <div style="font-size:12px;font-weight:800;color:#fff;background:rgba(4,14,27,.85);padding:6px 9px;border-radius:999px;border:1px solid rgba(255,255,255,.45);white-space:nowrap;">${night ? moonPhase : 'Sunrise ↗ Sunset'}</div>
        </div>
      </div>
      <div style="position:absolute;left:10px;right:10px;bottom:10px;display:flex;justify-content:space-between;align-items:flex-end;gap:10px;background:rgba(5,15,29,.89);border:1px solid rgba(255,255,255,.25);border-radius:12px;padding:12px;box-shadow:0 5px 18px rgba(0,0,0,.3);">
        <div style="font-size:14px;font-weight:800;color:#fff;line-height:1.45;text-shadow:0 1px 3px #000;">
          <div>${sunText}</div>
          <div style="color:#f2f7ff;font-weight:700;margin-top:4px;">${night ? 'Approximate lunar phase' : 'Live solar path · east to west'}</div>
        </div>
        <div style="font-size:13px;font-weight:800;color:#ffffff;text-align:right;line-height:1.55;text-shadow:0 1px 3px #000;">
          <div>↑ ${sunriseText} ${night ? 'next rise' : 'sunrise'}</div>
          <div>↓ ${sunsetText} ${night ? 'next set' : 'sunset'}</div>
        </div>
      </div>
    </div>`;
]]]

cards.label:
[[[
  const ids = ["media_player.dwelldeck_slot_283", "media_player.dwelldeck_slot_271", "media_player.dwelldeck_slot_282", "media_player.dwelldeck_slot_274", "media_player.dwelldeck_slot_270", "media_player.dwelldeck_slot_268", "media_player.dwelldeck_slot_273", "media_player.dwelldeck_slot_276", "media_player.dwelldeck_slot_269", "media_player.dwelldeck_slot_278", "media_player.dwelldeck_slot_277", "media_player.dwelldeck_slot_280", "media_player.dwelldeck_slot_284", "media_player.dwelldeck_slot_272", "media_player.dwelldeck_slot_281", "media_player.dwelldeck_slot_279", "media_player.dwelldeck_slot_285"];
  const playing=ids.filter(id=>states[id]?.state==='playing');
  const paused=ids.filter(id=>states[id]?.state==='paused');
  const readable=(id)=>states[id]?.attributes?.friendly_name||id.split('.')[1].replaceAll('_',' ');
  const detail=(id)=>{
    const e=states[id];
    const track=e?.attributes?.media_title||e?.attributes?.media_channel||'';
    const artist=e?.attributes?.media_artist||'';
    const short=s=>s.length>37?s.slice(0,35)+'…':s;
    return short(readable(id))+(track?' · '+short(track):'')+(artist?' — '+short(artist):'');
  };
  if(playing.length){
    const rows=playing.slice(0,2).map(detail);
    return `${playing.length} playing\n${rows.join('\n')}${playing.length>2?'\n+'+(playing.length-2)+' more':''}`;
  }
  if(paused.length) return `${paused.length} paused\n${paused.slice(0,2).map(readable).join(' · ')}`;
  return 'No music playing';
]]]

custom_fields.status:
[[[ const ids=['climate.dwelldeck_slot_143','climate.dwelldeck_slot_138','climate.dwelldeck_slot_140','climate.dwelldeck_slot_141','climate.dwelldeck_slot_142','climate.dwelldeck_slot_139'];
    const names=['Nature Mini Pro','__DWELLDECK_LABEL_05__','__DWELLDECK_LABEL_06__','Master bedroom','Master dressing','Electric room'];
    const stat=(id)=>{
      const e=states[id];
      if(!e || ['unknown','unavailable'].includes(e.state)) return {text:'Unavailable',color:'#f3ac76',sub:''};
      if(e.state==='off') return {text:'OFF',color:'#91a8bd',sub:''};
      const action=e.attributes?.hvac_action;
      if(action==='cooling') return {text:'COOLING',color:'#29d5ee',sub:''};
      if(action==='heating') return {text:'HEATING',color:'#f5af7d',sub:''};
      if(action==='drying') return {text:'DRYING',color:'#9e9cf2',sub:''};
      if(action==='fan') return {text:'FAN',color:'#39e2bc',sub:''};
      if(action==='idle') return {text:'IDLE',color:'#ffd16b',sub:''};
      return {text:e.state.toUpperCase(),color:'#d4c7ff',sub:''};
    };
    const temp=(e)=>{const n=Number(e?.attributes?.current_temperature);return Number.isFinite(n)?`${n.toFixed(1)}°C`:'—';};
    const target=(e)=>{const n=Number(e?.attributes?.temperature);return e?.attributes?.temperature!=null && Number.isFinite(n)?`${n.toFixed(0)}°C`:'—';};
    const rows=ids.map((id,i)=>{const e=states[id];const st=stat(id);return `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:7px 2px;border-bottom:1px solid rgba(156,199,225,.1);"><span style="color:#edf5ff;font-size:13px;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${names[i]}</span><span style="font-size:10px;font-weight:800;letter-spacing:.3px;color:${st.color};">${st.text}</span><span style="font-size:11px;color:#b7cadd;text-align:right;min-width:68px;">${temp(e)} / ${target(e)}</span></div>`;}).join('');
    const active=ids.filter(id=>states[id]&&!['off','unknown','unavailable'].includes(states[id].state)).length;
    return `<div style="width:100%;"><div style="display:flex;justify-content:space-between;align-items:center;padding-bottom:5px;color:#edf5ff;"><span style="font-size:14px;font-weight:700;">Air conditioning · Live status</span><span style="font-size:11px;color:#91a8bd;">${active} of 6 enabled</span></div>${rows}<div style="font-size:10px;color:#91a8bd;padding-top:7px;">Room °C / Set °C · Enabled does not always mean actively cooling</div></div>`;
    ]]]

