{% set ids = ['binary_sensor.dwelldeck_slot_016', 'binary_sensor.dwelldeck_slot_073', 'binary_sensor.dwelldeck_slot_081', 'binary_sensor.dwelldeck_slot_107', 'binary_sensor.dwelldeck_slot_108', 'binary_sensor.dwelldeck_slot_109', 'binary_sensor.dwelldeck_slot_110', 'binary_sensor.dwelldeck_slot_006', 'binary_sensor.dwelldeck_slot_007', 'binary_sensor.dwelldeck_slot_014', 'binary_sensor.dwelldeck_slot_015', 'binary_sensor.dwelldeck_slot_017', 'binary_sensor.dwelldeck_slot_018', 'binary_sensor.dwelldeck_slot_019', 'binary_sensor.dwelldeck_slot_020', 'binary_sensor.dwelldeck_slot_021', 'binary_sensor.dwelldeck_slot_022', 'binary_sensor.dwelldeck_slot_023', 'binary_sensor.dwelldeck_slot_025', 'binary_sensor.dwelldeck_slot_032', 'binary_sensor.dwelldeck_slot_053', 'binary_sensor.dwelldeck_slot_066', 'binary_sensor.dwelldeck_slot_067', 'binary_sensor.dwelldeck_slot_069', 'binary_sensor.dwelldeck_slot_090', 'binary_sensor.dwelldeck_slot_092', 'binary_sensor.dwelldeck_slot_100', 'binary_sensor.dwelldeck_slot_101'] %}
{% set ns = namespace(active=[]) %}{% for id in ids %}{% if is_state(id,'on') %}{% set ns.active=ns.active+[state_attr(id,'friendly_name') or id] %}{% endif %}{% endfor %}
