card_mod.style:
{% set s = states('cover.dwelldeck_slot_160') %}
{% set pos = state_attr('cover.dwelldeck_slot_160', 'current_position') %}
{% set p = ([[pos | float(100 if s == 'open' else 0), 0] | max, 100] | min) / 100 %}
{% set r = (75 + 180*p) | round(0) | int %}
{% set g = (154 + 55*p) | round(0) | int %}
{% set b = (238 - 131*p) | round(0) | int %}
ha-card {
 background: linear-gradient(135deg, rgba({{ r }}, {{ g }}, {{ b }}, .24), #172638);
 border: 1px solid {% if s in ['unknown','unavailable'] %}#a96e71{% else %}rgba({{ r }}, {{ g }}, {{ b }}, .70){% endif %};
